        x_flat = x.reshape(batch_size, -1)

        # Flatten weight and bias to 1D
        weight_flat = weight.reshape(-1)
        bias_flat = bias.reshape(-1)

        # Call fused HIP kernel
        output_flat = layer_norm_hip.layer_norm_hip(x_flat, weight_flat, bias_flat, self.eps)

        # Reshape output back to original shape
        return output_flat.reshape(x.shape)

