#include <hip/hip_runtime.h>
#include <math.h>

#define THREADS_PER_BLOCK 256
#define VEC_SIZE 2  // Vectorized loads for better memory bandwidth
#define ITEMS_PER_WARP 32

template<int vec_size>
__device__ __forceinline__ void vec_load(const float* ptr, float* out) {
    // Vectorized load for better memory coalescing
    *reinterpret_cast<float2*>(out) = *reinterpret_cast<const float2*>(ptr);
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    // Warp shuffle reduction for efficient sum
    #pragma unroll
    for (int mask = 16; mask > 0; mask >>= 1) {
        val += __shfl_xor(val, mask);
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_max(float val) {
    // Warp shuffle reduction for max
    #pragma unroll
    for (int mask = 16; mask > 0; mask >>= 1) {
        val = fmaxf(val, __shfl_xor(val, mask));
    }
    return val;
}

__global__ void layer_norm_optimized_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int total_elements,
    int normalized_size,
    float eps
) {
    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (global_idx >= total_elements) return;

    // Each warp processes one batch element
    int warp_id_in_block = threadIdx.x / 32;
    int lane = threadIdx.x % 32;
    int batch_idx = blockIdx.x * (blockDim.x / ITEMS_PER_WARP) + warp_id_in_block;

    if (batch_idx >= total_elements / normalized_size) return;

    const float* batch_input = input + batch_idx * normalized_size;
    float* batch_output = output + batch_idx * normalized_size;

    __shared__ float shared_mean[32];
    __shared__ float shared_rstd[32];

    // Phase 1: Parallel reduction for mean
    float local_sum = 0.0f;
    int num_iterations = (normalized_size + 31) / 32; // Items per warp

    for (int i = lane; i < normalized_size; i += 32) {
        float val = batch_input[i];
        local_sum += val;
    }

    // Warp reduction using shuffle - all threads in warp participate
    local_sum = warp_reduce_sum(local_sum);

    // Lane 0 stores the mean
    if (lane == 0) {
        float mean = local_sum / normalized_size;
        shared_mean[warp_id_in_block] = mean;
    }
    __syncthreads();

    // Phase 2: Parallel reduction for variance (re-use the same warp pattern)
    float local_var_sum = 0.0f;
    float mean_val = shared_mean[warp_id_in_block];

    for (int i = lane; i < normalized_size; i += 32) {
        float diff = batch_input[i] - mean_val;
        local_var_sum += diff * diff;
    }

    // Warp reduction for variance
    local_var_sum = warp_reduce_sum(local_var_sum);

    // Lane 0 computes and stores rstd (reciprocal sqrt)
    if (lane == 0) {
        float variance = local_var_sum / normalized_size;
        float rstd = rsqrtf(variance + eps);
        shared_rstd[warp_id_in_block] = rstd;
    }
    __syncthreads();

    // Phase 3: Fused normalize, scale, and bias with vectorized writes
    float mean_final = shared_mean[warp_id_in_block];
    float rstd_final = shared_rstd[warp_id_in_block];

    // Use grid-stride approach for better coalescing
    for (int i = global_idx; i < total_elements; i += gridDim.x * blockDim.x) {
        int sample_idx = i / normalized_size;
        int feature_idx = i % normalized_size;

        // Each thread processes multiple elements (grid stride)
        float val = input[i];
        float normalized = (val - mean_final) * rstd_final;
        output[i] = normalized * weight[feature_idx] + bias[feature_idx];
    }
